INSERT OR REPLACE INTO compliance_deadlines (id, effective_date, title, summary, legal_basis, applies_to, status, changed_by, original_date, sort_order, updated_at) VALUES ('dl_2024_08_01_entry_into_force', '2024-08-01', 'AI Act enters into force', 'Regulation (EU) 2024/1689 (the AI Act) entered into force. No obligations applied yet; the phased application calendar started running.', 'Article 113, Regulation (EU) 2024/1689', '["providers","deployers","importers","distributors"]', 'confirmed', NULL, NULL, 10, datetime('now'));
INSERT OR REPLACE INTO compliance_deadlines (id, effective_date, title, summary, legal_basis, applies_to, status, changed_by, original_date, sort_order, updated_at) VALUES ('dl_2025_02_02_prohibitions_literacy', '2025-02-02', 'Prohibited practices banned; AI literacy obligation applies', 'Article 5 prohibitions (social scoring, manipulative or exploitative AI, untargeted facial-image scraping, emotion recognition in workplaces and schools, most real-time remote biometric identification) became enforceable. Article 4 AI literacy applies to providers and deployers.', 'Articles 4 and 5; Article 113(a)', '["providers","deployers"]', 'confirmed', NULL, NULL, 20, datetime('now'));
INSERT OR REPLACE INTO compliance_deadlines (id, effective_date, title, summary, legal_basis, applies_to, status, changed_by, original_date, sort_order, updated_at) VALUES ('dl_2025_08_02_gpai_governance', '2025-08-02', 'GPAI model obligations, governance and penalty framework apply', 'Chapter V obligations for providers of general-purpose AI models (technical documentation, downstream information, copyright policy, public training-content summary; extra duties for systemic-risk models) apply to models placed on the market from this date. Member States had to designate national competent authorities. The penalty framework (Article 99) applies, except Commission fines on GPAI providers, which start one year later.', 'Chapter V (Articles 51-56); Chapter VII; Article 99; Article 113(b)', '["gpai_providers","member_states"]', 'confirmed', NULL, NULL, 30, datetime('now'));
INSERT OR REPLACE INTO compliance_deadlines (id, effective_date, title, summary, legal_basis, applies_to, status, changed_by, original_date, sort_order, updated_at) VALUES ('dl_2026_07_27_omnibus_in_force', '2026-07-27', 'Digital Omnibus on AI enters into force', 'Regulation (EU) 2026/1744, published in the Official Journal on 24 July 2026, amended the AI Act three days after publication. It deferred high-risk obligations, softened Article 4, added a prohibition on non-consensual intimate imagery and CSAM generation, extended SME relief to small mid-caps and reorganised some enforcement competences.', 'Regulation (EU) 2026/1744', '["providers","deployers","gpai_providers"]', 'confirmed', 'Regulation (EU) 2026/1744', NULL, 40, datetime('now'));
INSERT OR REPLACE INTO compliance_deadlines (id, effective_date, title, summary, legal_basis, applies_to, status, changed_by, original_date, sort_order, updated_at) VALUES ('dl_2026_08_02_transparency_enforcement', '2026-08-02', 'Article 50 transparency obligations apply; enforcement powers activate', 'Chatbot disclosure, machine-readable marking of AI-generated content, emotion-recognition and biometric-categorisation disclosure, and deepfake and public-interest text labelling apply. The AI Office and national market-surveillance authorities can now exercise their enforcement powers, and the Commission can fine GPAI providers up to EUR 15 million or 3% of worldwide turnover.', 'Article 50; Articles 74-94; Article 101; Article 113', '["providers","deployers","gpai_providers"]', 'confirmed', NULL, NULL, 50, datetime('now'));
INSERT OR REPLACE INTO compliance_deadlines (id, effective_date, title, summary, legal_basis, applies_to, status, changed_by, original_date, sort_order, updated_at) VALUES ('dl_2026_12_02_marking_grace_period', '2026-12-02', 'Grace period ends for machine-readable marking on legacy generative systems', 'Generative AI systems placed on the market or put into service before 2 August 2026 must implement Article 50(2) machine-readable marking of synthetic output by this date. Systems placed on the market from 2 August 2026 had to comply immediately.', 'Article 50(2) as amended by Regulation (EU) 2026/1744', '["providers"]', 'confirmed', 'Regulation (EU) 2026/1744', '2026-08-02', 60, datetime('now'));
INSERT OR REPLACE INTO compliance_deadlines (id, effective_date, title, summary, legal_basis, applies_to, status, changed_by, original_date, sort_order, updated_at) VALUES ('dl_2027_02_02_watermark_interoperability', '2027-02-02', 'Watermark-detection interoperability commitment (Transparency Code of Practice)', 'Signatories of the Code of Practice on marking and labelling AI-generated content commit to providing detection tools and an interoperability solution for watermark detection by this date. Voluntary for non-signatories, but the Commission treats Code adherence as evidence of Article 50 compliance.', 'Code of Practice on Transparency of AI-Generated Content (Article 50; Article 56)', '["providers"]', 'confirmed', NULL, NULL, 70, datetime('now'));
INSERT OR REPLACE INTO compliance_deadlines (id, effective_date, title, summary, legal_basis, applies_to, status, changed_by, original_date, sort_order, updated_at) VALUES ('dl_2027_08_02_legacy_gpai', '2027-08-02', 'Legacy GPAI models must comply', 'Providers of general-purpose AI models placed on the market before 2 August 2025 must bring them into compliance with Chapter V obligations by this date.', 'Article 111(3)', '["gpai_providers"]', 'confirmed', NULL, NULL, 80, datetime('now'));
INSERT OR REPLACE INTO compliance_deadlines (id, effective_date, title, summary, legal_basis, applies_to, status, changed_by, original_date, sort_order, updated_at) VALUES ('dl_2027_12_02_annex_iii_high_risk', '2027-12-02', 'Stand-alone high-risk AI (Annex III) obligations apply at the latest', 'Requirements for high-risk AI systems in Annex III areas (biometrics, critical infrastructure, education, employment, essential services, law enforcement, migration, justice) apply six months after the Commission confirms that harmonised standards, common specifications and guidance are available, and no later than this backstop date. Originally 2 August 2026.', 'Article 113 as amended by Regulation (EU) 2026/1744; Articles 6, 8-27, 43, 49, 72-73', '["providers","deployers","importers","distributors"]', 'backstop', 'Regulation (EU) 2026/1744', '2026-08-02', 90, datetime('now'));
INSERT OR REPLACE INTO compliance_deadlines (id, effective_date, title, summary, legal_basis, applies_to, status, changed_by, original_date, sort_order, updated_at) VALUES ('dl_2028_08_02_annex_i_high_risk', '2028-08-02', 'High-risk AI embedded in regulated products (Annex I) obligations apply at the latest', 'Requirements for AI that is a safety component of, or is itself, a product covered by Annex I harmonisation legislation (medical devices, machinery, toys, lifts, vehicles, aviation and others) apply twelve months after the Commission''s standards-availability decision, and no later than this backstop date. Originally 2 August 2027.', 'Article 113 as amended by Regulation (EU) 2026/1744; Article 6(1); Annex I', '["providers","deployers","importers","distributors"]', 'backstop', 'Regulation (EU) 2026/1744', '2027-08-02', 100, datetime('now'));

INSERT OR REPLACE INTO regulatory_updates (id, published_on, title, summary, category, impact, affected_roles, sources, updated_at) VALUES ('upd_2026_08_02_enforcement_transparency_live', '2026-08-02', 'AI Office and national authorities begin enforcing the AI Act; Article 50 transparency rules apply', 'From 2 August 2026 the Commission''s AI Office and national market-surveillance authorities can exercise their enforcement powers. Article 50 transparency duties apply: people must be told when they interact with an AI system, generative AI output must carry machine-readable marks, deepfakes and AI-generated public-interest text must be labelled, and emotion-recognition or biometric-categorisation use must be disclosed. The Commission can now fine GPAI providers up to EUR 15 million or 3% of worldwide turnover, including for breaches dating back to 2 August 2025.', 'enforcement', 'high', '["providers","deployers","gpai_providers"]', '[{"title":"European Commission press release: Commission starts enforcing AI Act rules and new transparency obligations","url":"https://ec.europa.eu/commission/presscorner/detail/en/ip_26_1714"},{"title":"European Commission: Safer and more transparent AI (2 August 2026)","url":"https://commission.europa.eu/news-and-media/news/safer-and-more-transparent-ai-2026-08-02_en"},{"title":"Al Jazeera: What came into force with the EU''s AI Act this week, and what didn''t","url":"https://www.aljazeera.com/news/2026/8/6/what-came-into-force-with-the-eus-ai-act-this-week-and-what-didnt"}]', datetime('now'));
INSERT OR REPLACE INTO regulatory_updates (id, published_on, title, summary, category, impact, affected_roles, sources, updated_at) VALUES ('upd_2026_07_27_omnibus_in_force', '2026-07-27', 'Digital Omnibus on AI (Regulation (EU) 2026/1744) enters into force', 'Published in the Official Journal on 24 July 2026 and in force three days later. Stand-alone high-risk (Annex III) obligations are deferred to six months after a Commission decision confirming that standards and guidance are available, with a backstop of 2 December 2027; Annex I embedded high-risk AI gets twelve months and a backstop of 2 August 2028. Generative systems already on the market get until 2 December 2026 for machine-readable marking. Article 4 now requires providers and deployers to take measures supporting AI literacy rather than guaranteeing a level of literacy. A new prohibition covers AI designed to generate non-consensual intimate imagery or child sexual abuse material. SME simplifications extend to small mid-caps. Article 6(3) self-assessed systems must still be registered, via a simplified procedure. The legal basis for processing special-category data for bias detection extends to all AI systems under a strict-necessity test. The AI Office gains exclusive supervision of AI systems built on a provider''s own GPAI model and of systems integrated in very large online platforms and search engines.', 'legislation', 'high', '["providers","deployers","gpai_providers","importers","distributors"]', '[{"title":"EUR-Lex: Regulation (EU) 2026/1744","url":"https://eur-lex.europa.eu/eli/reg/2026/1744/oj/eng"},{"title":"European Commission: AI Omnibus enters into force","url":"https://digital-strategy.ec.europa.eu/en/news/ai-omnibus-enters-force"},{"title":"White & Case: EU AI Omnibus enters into force, amending the AI Act","url":"https://www.whitecase.com/insight-alert/eu-ai-omnibus-enters-force-amending-ai-act"},{"title":"Lewis Silkin: The Digital Omnibus on AI enters into force today","url":"https://www.lewissilkin.com/en/insights/2026/07/27/the-digital-omnibus-on-ai-enters-into-force-today-102nedo"}]', datetime('now'));
INSERT OR REPLACE INTO regulatory_updates (id, published_on, title, summary, category, impact, affected_roles, sources, updated_at) VALUES ('upd_2026_07_transparency_code_adequate', '2026-07-20', 'Commission confirms Transparency Code of Practice as adequate and publishes final Article 50 guidelines', 'The AI Office finalised the Code of Practice on marking and labelling AI-generated content and the Commission published its final guidelines on Article 50 transparency obligations. The Code operationalises the provider marking duty (Article 50(2)) and the deployer labelling duty (Article 50(4)). Content generated before 2 August 2026 need not be marked retroactively. Signatories commit to watermark-detection interoperability by 2 February 2027.', 'code_of_practice', 'high', '["providers","deployers"]', '[{"title":"Faegre Drinker: Commission confirms Transparency Code of Practice as adequate and publishes final guidelines","url":"https://www.faegredrinker.com/en/insights/publications/2026/7/eu-ai-act-commission-confirms-transparency-code-of-practice-as-adequate-and-publishes-final-version-of-its-guidelines-on-transparency-obligations"},{"title":"Bird & Bird: The final Transparency Code of Practice","url":"https://www.twobirds.com/en/insights/2026/taking-the-eu-ai-act-to-practice-the-final-transparency-code-of-practice"},{"title":"Addleshaw Goddard: Code of Practice on marking and labelling AI-generated content","url":"https://www.addleshawgoddard.com/en/insights/insights-briefings/2026/technology/eu-ai-act-code-practice-marking-labelling-ai-generated-content/"}]', datetime('now'));
INSERT OR REPLACE INTO regulatory_updates (id, published_on, title, summary, category, impact, affected_roles, sources, updated_at) VALUES ('upd_2026_07_12_en_18286_approved', '2026-07-12', 'EN 18286:2026 approved: first AI Act harmonised-standard candidate (quality management, Article 17)', 'CEN and CENELEC approved EN 18286:2026 ''Artificial intelligence - Quality management system for EU AI Act regulatory purposes'', drafted by CEN-CLC/JTC 21 under standardisation request M/613. It specifies the Article 17 quality management system for providers of high-risk AI systems across the AI lifecycle. It is not yet cited in the Official Journal, so it does not yet confer a presumption of conformity. Companion drafts remain in progress: prEN 18228 (risk management), prEN 18229 (trustworthiness framework: logging, transparency, human oversight), prEN 18282 (cybersecurity) and prEN 18284 (data quality and governance).', 'standards', 'medium', '["providers"]', '[{"title":"CEN-CENELEC: EN 18286 in the spotlight","url":"https://www.cencenelec.eu/news-events/news/2026/en-in-the-spotlight/2026-07-30-ai-quality-management/"},{"title":"BSI: EN 18286:2026 provides a framework for AI quality management under the EU AI Act","url":"https://www.bsigroup.com/en-GB/insights-and-media/media-centre/press-releases/2026/july/en-18286-provides-a-framework-for-ai-quality-management-under-the-eu-ai-act/"},{"title":"Adam Leon Smith: EN 18286:2026 is finally published","url":"https://adamleonsmith.substack.com/p/en-182862026-is-finally-published"}]', datetime('now'));
INSERT OR REPLACE INTO regulatory_updates (id, published_on, title, summary, category, impact, affected_roles, sources, updated_at) VALUES ('upd_2026_06_29_council_adopts_omnibus', '2026-06-29', 'Council formally adopts the Digital Omnibus on AI', 'Following the European Parliament''s plenary vote on 16 June 2026 (423 in favour, 57 against, 174 abstentions), the Council gave final approval on 29 June 2026, clearing the way for publication in the Official Journal.', 'legislation', 'high', '["providers","deployers","gpai_providers"]', '[{"title":"Sofia Globe: European Parliament approves AI Act amendments, ''nudifier'' ban","url":"https://sofiaglobe.com/2026/06/16/european-parliament-approves-ai-act-amendments-nudifier-ban/"},{"title":"iubenda: Parliament adopts the AI Omnibus, Council sign-off next","url":"https://www.iubenda.com/en/blog/ai-omnibus-parliament-adoption-june-2026/"},{"title":"Sidley: EU lawmakers reach provisional agreement to delay key EU AI Act obligations","url":"https://datamatters.sidley.com/2026/06/22/eu-lawmakers-reach-provisional-agreement-to-delay-key-eu-ai-act-obligations/"}]', datetime('now'));
INSERT OR REPLACE INTO regulatory_updates (id, published_on, title, summary, category, impact, affected_roles, sources, updated_at) VALUES ('upd_2026_05_07_provisional_agreement', '2026-05-07', 'Council and Parliament reach provisional agreement on the Digital Omnibus on AI', 'Trilogue negotiators agreed the compromise text: deferral of high-risk obligations with hard backstops, a four-month marking grace period for legacy generative systems, a softened Article 4, the new prohibition on non-consensual intimate content and CSAM generation, and retention of Article 6(3) registration in simplified form.', 'legislation', 'high', '["providers","deployers","gpai_providers"]', '[{"title":"Council of the EU press release: Artificial intelligence - Council and Parliament agree to simplify and streamline rules","url":"https://www.consilium.europa.eu/en/press/press-releases/2026/05/07/artificial-intelligence-council-and-parliament-agree-to-simplify-and-streamline-rules/"},{"title":"Gibson Dunn: EU AI Act Omnibus agreement - postponed high-risk deadlines and other key changes","url":"https://www.gibsondunn.com/eu-ai-act-omnibus-agreement-postponed-high-risk-deadlines-and-other-key-changes/"},{"title":"William Fry: Omnibus deal reached - postponed deadlines, watermarking compromise and the nudification prohibition","url":"https://www.williamfry.com/knowledge/eu-ai-act-omnibus-deal-reached-postponed-deadlines-watermarking-compromise-and-the-nudificiation-prohibition/"}]', datetime('now'));
INSERT OR REPLACE INTO regulatory_updates (id, published_on, title, summary, category, impact, affected_roles, sources, updated_at) VALUES ('upd_2025_11_19_omnibus_proposal', '2025-11-19', 'Commission proposes the Digital Omnibus on AI', 'The Commission proposed targeted amendments to the AI Act to link high-risk application dates to the availability of harmonised standards, simplify obligations for smaller companies and centralise some supervision in the AI Office.', 'legislation', 'medium', '["providers","deployers","gpai_providers"]', '[{"title":"DLA Piper: The Digital AI Omnibus - proposed deferral of high-risk AI obligations","url":"https://knowledge.dlapiper.com/dlapiperknowledge/globalemploymentlatestdevelopments/2026/The-Digital-AI-Omnibus-Proposed-deferral-of-high-risk-AI-obligations-under-the-AI-Act"},{"title":"European Parliament Legislative Train: Digital Omnibus on AI","url":"https://www.europarl.europa.eu/legislative-train/package-digital-package/file-digital-omnibus-on-ai"}]', datetime('now'));
INSERT OR REPLACE INTO regulatory_updates (id, published_on, title, summary, category, impact, affected_roles, sources, updated_at) VALUES ('upd_2025_08_02_gpai_obligations_apply', '2025-08-02', 'GPAI model obligations apply; national authorities designated', 'Chapter V obligations for providers of general-purpose AI models apply to models placed on the market from this date. Models already on the market have until 2 August 2027. Commission enforcement against GPAI providers starts on 2 August 2026.', 'legislation', 'high', '["gpai_providers","member_states"]', '[{"title":"Latham & Watkins: GPAI model obligations in force and final GPAI Code of Practice in place","url":"https://www.lw.com/en/insights/eu-ai-act-gpai-model-obligations-in-force-and-final-gpai-code-of-practice-in-place"},{"title":"European Commission: AI Act policy page","url":"https://digital-strategy.ec.europa.eu/en/policies/regulatory-framework-ai"}]', datetime('now'));
INSERT OR REPLACE INTO regulatory_updates (id, published_on, title, summary, category, impact, affected_roles, sources, updated_at) VALUES ('upd_2025_07_10_gpai_code_and_guidelines', '2025-07-10', 'Final GPAI Code of Practice published; Commission GPAI guidelines and training-data summary template follow', 'The AI Office published the final General-Purpose AI Code of Practice with chapters on Transparency, Copyright, and Safety and Security. Later in July 2025 the Commission issued guidelines clarifying the scope of GPAI obligations and a mandatory template for the public summary of training content.', 'guidance', 'medium', '["gpai_providers"]', '[{"title":"Jones Day: European Commission publishes General-Purpose AI Code of Practice","url":"https://www.jonesday.com/en/insights/2025/08/eu-ai-act-european-commission-publishes-generalpurpose-ai-code-of-practice"},{"title":"Paul, Weiss: Commission publishes guidelines on GPAI obligations and training-data disclosure template","url":"https://www.paulweiss.com/insights/client-memos/eu-commission-publishes-guidelines-on-general-purpose-ai-obligations-as-well-as-training-data-disclosure-template-further-clarity-as-the-countdown-to-enforcement-begins"},{"title":"WilmerHale: Commission issues guidelines for providers of GPAI models","url":"https://www.wilmerhale.com/en/insights/blogs/wilmerhale-privacy-and-cybersecurity-law/20250724-european-commission-issues-guidelines-for-providers-of-general-purpose-ai-models"}]', datetime('now'));

INSERT OR REPLACE INTO training_modules (id, title, description, category, tier_required, duration_min, order_index, content_version, regulatory_basis, content, is_published, updated_at) VALUES ('mod_foundation_01', 'What Is the EU AI Act?', 'Understand the world''s first comprehensive AI regulation, why it exists, who it affects, and the key deadlines as amended by the 2026 Digital Omnibus.', 'foundation', 'free', 20, 1, '2026.09', '["Regulation (EU) 2024/1689","Regulation (EU) 2026/1744","Article 4","Article 5","Article 99","Article 113"]', '{"sections":[{"title":"Why the EU Regulates AI","body":"The EU AI Act (Regulation (EU) 2024/1689) entered into force on 1 August 2024. It is the world''s first comprehensive legal framework for artificial intelligence, designed to ensure AI systems used in the EU are safe, transparent, and respect fundamental rights.\n\nThe regulation applies to any organisation that develops, deploys, or uses AI systems whose outputs affect people within the EU, regardless of where the organisation is based. This extraterritorial reach means that even companies outside Europe must comply if their AI systems interact with EU citizens.\n\nIn 2026 the Act was amended by the Digital Omnibus on AI (Regulation (EU) 2026/1744), which entered into force on 27 July 2026. The Omnibus reset several deadlines and simplified some obligations, but it did not change the Act''s core structure or its requirements. This module reflects the amended text."},{"title":"The Risk-Based Approach","body":"The AI Act classifies AI systems into four risk tiers:\n\n• Unacceptable Risk: banned outright. Includes social scoring, subliminal or exploitative manipulation, emotion recognition in workplaces and schools, untargeted scraping of facial images, most real-time remote biometric identification in public spaces and, since the 2026 amendments, AI designed to generate non-consensual intimate imagery or child sexual abuse material.\n\n• High Risk: subject to strict requirements including risk management, data governance, technical documentation, human oversight, and conformity assessment. Listed in Annex III (stand-alone use cases) and Annex I (AI in regulated products).\n\n• Limited Risk: transparency obligations apply. People must be told they are interacting with AI, and AI-generated content must be marked and, in some cases, labelled.\n\n• Minimal Risk: no specific obligations, but voluntary codes of conduct are encouraged.\n\nIn addition, general-purpose AI (GPAI) models such as large language models carry their own obligations under Chapter V, regardless of the risk tier of the systems built on top of them."},{"title":"Key Deadlines (as amended in 2026)","body":"The regulation is phased in over several years. The current calendar is:\n\n• 2 February 2025: prohibited practices banned; AI literacy obligation (Article 4) applies.\n\n• 2 August 2025: GPAI model obligations apply; national authorities designated; penalty framework in place.\n\n• 2 August 2026: Article 50 transparency obligations apply (chatbot disclosure, machine-readable marking of AI-generated content, deepfake labelling). The AI Office and national authorities'' enforcement powers apply, including Commission fines on GPAI providers.\n\n• 2 December 2026: end of the grace period for generative AI systems that were already on the market before 2 August 2026 to implement machine-readable marking.\n\n• 2 December 2027 at the latest: obligations for stand-alone high-risk systems (Annex III). They can apply earlier: six months after the Commission confirms that harmonised standards and guidance are available.\n\n• 2 August 2028 at the latest: obligations for high-risk AI embedded in regulated products (Annex I); twelve months after that same Commission decision.\n\nNon-compliance can result in fines of up to EUR 35 million or 7% of global annual turnover for prohibited practices, and up to EUR 15 million or 3% for most other obligations. SMEs and, since 2026, small mid-caps pay the lower of the two amounts."},{"title":"What AI Literacy Means for You","body":"Article 4 requires providers and deployers to take measures that support a sufficient level of AI literacy among staff and other people who operate or use AI systems on their behalf. The 2026 amendments clarified that organisations do not have to guarantee a specific level of literacy for any individual, and that the Commission and Member States will support these efforts, including by publishing practical examples of compliance.\n\nThe practical expectation is unchanged: everyone who works with AI outputs needs to understand what the system can and cannot do, how to interpret its results, when human oversight is needed, and what their responsibilities are under the regulation. This is not just for developers. It includes managers, customer service representatives, HR staff, and anyone who makes decisions based on AI output.\n\nCompleting this training, and keeping a record of completion, is one concrete way to demonstrate that your organisation has taken the measures Article 4 requires."}],"quiz":[{"question":"When did AI literacy obligations under Article 4 come into force?","options":["1 August 2024","2 February 2025","2 August 2026","2 December 2027"],"correct":1,"explanation":"AI literacy obligations and the prohibited-practice bans took effect on 2 February 2025. The 2026 amendments softened the wording of Article 4 but did not change the date."},{"question":"Which risk tier results in AI systems being banned?","options":["High Risk","Limited Risk","Unacceptable Risk","Minimal Risk"],"correct":2,"explanation":"Unacceptable-risk AI practices are prohibited under Article 5 of the EU AI Act."},{"question":"Does the EU AI Act apply to companies based outside the EU?","options":["No, only EU-based companies","Yes, if their AI outputs affect people in the EU","Only if they have an EU office","Only for high-risk systems"],"correct":1,"explanation":"The Act has extraterritorial reach. It applies to any provider or deployer whose AI system''s output is used in the EU."},{"question":"Under the 2026 amendments, what is the latest date on which stand-alone (Annex III) high-risk obligations apply?","options":["2 August 2026","2 December 2026","2 December 2027","2 August 2028"],"correct":2,"explanation":"The Digital Omnibus deferred Annex III high-risk obligations to six months after a Commission decision on standards availability, with a hard backstop of 2 December 2027. Annex I embedded systems have a backstop of 2 August 2028."},{"question":"What is the maximum fine for using prohibited AI practices?","options":["EUR 7.5 million or 1%","EUR 15 million or 3%","EUR 35 million or 7%","EUR 50 million or 10%"],"correct":2,"explanation":"Prohibited practices carry fines of up to EUR 35 million or 7% of global annual turnover, whichever is higher."}]}', 1, datetime('now'));
INSERT OR REPLACE INTO training_modules (id, title, description, category, tier_required, duration_min, order_index, content_version, regulatory_basis, content, is_published, updated_at) VALUES ('mod_update_2026', 'Regulatory Update: The 2026 Digital Omnibus', 'What changed when Regulation (EU) 2026/1744 amended the AI Act, what still applied on 2 August 2026, and what your organisation should do now.', 'foundation', 'free', 15, 2, '2026.09', '["Regulation (EU) 2026/1744","Article 4","Article 5","Article 6(3)","Article 10(5)","Article 50","Article 113"]', '{"sections":[{"title":"What the Digital Omnibus Is","body":"The Digital Omnibus on AI is a package of targeted amendments to the AI Act. The Commission proposed it on 19 November 2025 because the harmonised standards, common specifications and guidance that companies need to comply with the high-risk rules were running late.\n\nThe timeline:\n\n• 7 May 2026: Council and Parliament reach provisional political agreement.\n• 16 June 2026: Parliament plenary approves the text (423 in favour, 57 against, 174 abstentions).\n• 29 June 2026: Council gives final approval.\n• 24 July 2026: published in the Official Journal as Regulation (EU) 2026/1744.\n• 27 July 2026: entry into force, three days after publication because of the proximity of the original 2 August 2026 deadline.\n\nThe amendments are now part of the AI Act. Where this training refers to ''the Act'', it means the amended text."},{"title":"The New High-Risk Timeline","body":"The most important change is a ''stop-the-clock'' mechanism for high-risk AI systems.\n\n• Stand-alone high-risk systems (Annex III): obligations apply six months after the Commission adopts a decision confirming that harmonised standards, common specifications and supporting guidance are available, and in any case no later than 2 December 2027.\n\n• High-risk AI embedded in regulated products (Annex I): obligations apply twelve months after that decision, and no later than 2 August 2028.\n\nWhat did not change: the substance of the high-risk requirements. Risk management (Article 9), data governance (Article 10), technical documentation (Article 11), logging (Article 12), transparency to deployers (Article 13), human oversight (Article 14), accuracy, robustness and cybersecurity (Article 15), the quality management system (Article 17), deployer duties (Article 26) and conformity assessment (Article 43) all still apply. The deadlines moved. The requirements did not.\n\nBecause the Commission decision could come well before the backstop dates, the effective deadline for a stand-alone system could be as early as mid-2027. Treat 2 December 2027 as the last possible date, not the planning date."},{"title":"What Still Applied on 2 August 2026","body":"Several obligations kept their original date:\n\n• Article 50 transparency obligations apply. People must be told when they interact with an AI system; providers of generative AI must mark output in a machine-readable way; deployers must label deepfakes and AI-generated text published to inform the public on matters of public interest; emotion recognition and biometric categorisation must be disclosed.\n\n• Enforcement powers of the AI Office and national market-surveillance authorities apply.\n\n• The Commission can now fine providers of general-purpose AI models up to EUR 15 million or 3% of worldwide turnover, including for breaches dating back to 2 August 2025.\n\nOne concession was made for transparency: generative AI systems placed on the market or put into service before 2 August 2026 have until 2 December 2026 to implement machine-readable marking (Article 50(2)). Systems placed on the market from 2 August 2026 must comply immediately.\n\nIn July 2026 the Commission confirmed the Code of Practice on marking and labelling AI-generated content as an adequate means of compliance and published its final guidelines on Article 50."},{"title":"Other Changes You Should Know","body":"• AI literacy (Article 4): providers and deployers must take measures to support AI literacy of their staff. They do not have to guarantee a specific level. The Commission and Member States will publish practical examples.\n\n• New prohibition (Article 5): AI practices aimed at generating non-consensual sexual or intimate imagery, or child sexual abuse material, are banned. So-called ''nudification'' tools fall squarely within this.\n\n• Article 6(3) self-assessment: the Commission had proposed dropping the EU-database registration for systems a provider self-assesses as not high-risk. The co-legislators kept the registration, in a simplified form. Document the assessment and register.\n\n• Small mid-caps: SME simplifications (simplified technical documentation, priority access to regulatory sandboxes, lower penalty caps) now also cover small mid-cap companies.\n\n• Bias detection data (Article 10(5)): the legal basis for processing special categories of personal data to detect and correct bias now covers providers and deployers of any AI system, subject to a strict-necessity test and safeguards.\n\n• Centralised supervision: the AI Office has exclusive supervisory competence over AI systems built on a GPAI model developed by the same provider or group, and over AI systems integrated into very large online platforms and search engines designated under the Digital Services Act."},{"title":"What To Do Now","body":"1. Do not pause high-risk preparation. Inventory, risk classification, Annex IV documentation and quality management take longer than the time left, and the Commission decision may start the six-month countdown before the backstop.\n\n2. Audit every customer-facing or content-generating AI system against Article 50. These rules are live now. If a legacy generative system is not yet marking output, it must be by 2 December 2026.\n\n3. Keep AI literacy training and completion records. The measures-based wording of Article 4 makes documented training the simplest evidence.\n\n4. Watch for the Commission''s standards-availability decision and for EN 18286 and its companion standards being cited in the Official Journal.\n\n5. If you are an SME or small mid-cap, use the simplified documentation form and sandbox access, but note the requirements are the same."}],"quiz":[{"question":"When did the Digital Omnibus on AI enter into force?","options":["2 August 2026","27 July 2026","7 May 2026","1 January 2027"],"correct":1,"explanation":"Regulation (EU) 2026/1744 was published in the Official Journal on 24 July 2026 and entered into force three days later, on 27 July 2026."},{"question":"What does the deferral of high-risk obligations mean in practice?","options":["High-risk requirements were removed","The deadlines moved; the requirements are unchanged","Only SMEs must comply","Annex III was deleted"],"correct":1,"explanation":"The Omnibus changed the application dates and linked them to a Commission decision on standards. The substantive requirements in Articles 9 to 17, 26 and 43 are unchanged."},{"question":"Which obligation applied on 2 August 2026 as originally scheduled?","options":["Annex III high-risk obligations","Article 50 transparency obligations","Annex I embedded high-risk obligations","None; everything was deferred"],"correct":1,"explanation":"Article 50 transparency duties and the enforcement powers of the AI Office and national authorities applied from 2 August 2026. Only the high-risk obligations were deferred."},{"question":"By when must generative AI systems already on the market before 2 August 2026 implement machine-readable marking?","options":["2 December 2026","2 February 2027","2 December 2027","2 August 2028"],"correct":0,"explanation":"The Omnibus gave legacy generative systems a four-month grace period for Article 50(2) marking, ending 2 December 2026."}]}', 1, datetime('now'));
INSERT OR REPLACE INTO training_modules (id, title, description, category, tier_required, duration_min, order_index, content_version, regulatory_basis, content, is_published, updated_at) VALUES ('mod_foundation_02', 'Understanding AI Systems', 'Learn what counts as an ''AI system'' under the Act, common AI technologies your organisation may already be using, and how to identify them.', 'foundation', 'starter', 25, 3, '2026.09', '["Article 3(1)","Article 3(63)","Article 25","Article 50"]', '{"sections":[{"title":"The Legal Definition of an AI System","body":"Under the EU AI Act, an ''AI system'' is a machine-based system designed to operate with varying levels of autonomy, that may exhibit adaptiveness after deployment, and that infers from inputs how to generate outputs such as predictions, content, recommendations, or decisions that can influence physical or virtual environments.\n\nThis definition is intentionally broad. It covers not just cutting-edge deep learning models but also traditional machine learning, rule-based systems with adaptive components, and many common business tools. The Commission''s guidelines on the definition (February 2025) confirm that simple systems with fixed, human-defined rules and no inference are outside the definition, but most software that learns from data is inside it."},{"title":"Common AI Systems in Business","body":"Your organisation likely already uses AI in ways you might not recognise:\n\n• Generative AI assistants and chat tools (ChatGPT, Claude, Gemini, Copilot). These are AI systems built on general-purpose AI models.\n• Customer support chatbots and voice bots\n• Email spam filters and content moderation tools\n• Recommendation engines (product suggestions, content curation)\n• HR screening tools (CV parsing, candidate ranking)\n• Predictive analytics (sales forecasting, demand planning, credit or fraud scoring)\n• Image recognition (quality control, document processing)\n• Translation, transcription and summarisation tools\n• Code generation assistants\n\nThe first step in compliance is identifying all AI systems in use, including AI features embedded in SaaS products you already pay for."},{"title":"Provider vs. Deployer Responsibilities","body":"The Act distinguishes between two key roles:\n\nProvider: the entity that develops an AI system, or has one developed, and places it on the market or puts it into service under its own name or trademark. Providers bear the heaviest obligations: risk management, documentation, conformity assessment, and machine-readable marking of generative output.\n\nDeployer: the entity that uses an AI system under its own authority in a professional capacity (but did not develop it). Deployers must use the system according to its instructions, maintain human oversight, monitor operation, tell people when they interact with AI, label deepfakes and certain AI-generated text, and cooperate with authorities.\n\nImportant: if you put your name on a third-party system, substantially modify it, or change its intended purpose, you may become the ''provider'' under Article 25 and inherit all provider obligations."}],"quiz":[{"question":"Which of the following is likely an AI system under the Act?","options":["A static FAQ page","A spreadsheet formula","A customer chatbot built on a large language model","A printed manual"],"correct":2,"explanation":"A chatbot powered by a large language model meets the definition: it is machine-based, operates with autonomy, and infers outputs that influence interactions."},{"question":"What happens if you substantially modify a third-party AI system?","options":["Nothing changes; the original provider is still responsible","You may become the ''provider'' and inherit provider obligations","The system is automatically banned","You only need to notify the original provider"],"correct":1,"explanation":"Under Article 25, substantial modifications that affect compliance or change the intended purpose make the modifier the new provider."},{"question":"What is the first step toward EU AI Act compliance?","options":["Hiring a compliance officer","Identifying all AI systems your organisation uses","Registering with the EU AI Office","Applying for CE marking"],"correct":1,"explanation":"You cannot assess risk or meet obligations if you don''t know which AI systems your organisation uses. Inventory is step one."}]}', 1, datetime('now'));
INSERT OR REPLACE INTO training_modules (id, title, description, category, tier_required, duration_min, order_index, content_version, regulatory_basis, content, is_published, updated_at) VALUES ('mod_foundation_03', 'Your Obligations & Responsibilities', 'Know what the AI Act requires from your organisation today, what is coming under the amended high-risk timeline, and your personal role in maintaining compliance.', 'foundation', 'starter', 20, 4, '2026.09', '["Article 4","Article 50","Articles 9-17","Article 26","Article 73"]', '{"sections":[{"title":"AI Literacy (Article 4): In Force Since February 2025","body":"Providers and deployers must take measures to support a sufficient level of AI literacy among staff and other people who operate or use AI systems on their behalf, taking into account their technical knowledge, experience, education and training, and the context in which the AI is used.\n\nSince the 2026 amendments the obligation is framed as taking measures, not guaranteeing an outcome. In practice, AI literacy means every person who works with AI:\n\n• Understands what the AI system does and its limitations\n• Knows when to trust AI outputs and when to exercise judgment\n• Is aware of potential biases and errors\n• Understands their role in human oversight\n• Knows how to escalate concerns about AI behaviour\n\nThis applies regardless of role, from the CEO to customer-facing staff. Keep records of who completed which training and when."},{"title":"Transparency Obligations (Article 50): In Force Since 2 August 2026","body":"If your organisation deploys or provides AI systems that interact with people or generate content, you must:\n\n• Inform people that they are interacting with an AI system, unless obvious from context (Article 50(1))\n• As a provider of generative AI, mark output (text, images, audio, video) in a machine-readable format so it can be detected as artificially generated (Article 50(2))\n• Disclose the operation of emotion recognition or biometric categorisation systems to the people exposed to them (Article 50(3))\n• As a deployer, label deepfakes, and label AI-generated or manipulated text published to inform the public on matters of public interest unless it has gone through human editorial review (Article 50(4))\n\nThese obligations apply to all AI systems that fall within them, not just high-risk ones. Generative systems that were already on the market before 2 August 2026 have until 2 December 2026 to implement machine-readable marking. The Commission''s Code of Practice on marking and labelling AI-generated content and its Article 50 guidelines (July 2026) describe accepted techniques."},{"title":"High-Risk System Requirements: Coming by December 2027 / August 2028","body":"If your organisation provides or deploys high-risk AI systems, the following requirements apply from six months (Annex III) or twelve months (Annex I) after the Commission confirms that standards are available, and no later than 2 December 2027 and 2 August 2028 respectively:\n\n• Risk management system (Article 9)\n• Data governance and quality controls (Article 10)\n• Technical documentation per Annex IV (Article 11)\n• Record-keeping and logging (Article 12)\n• Transparency and instructions for deployers (Article 13)\n• Human oversight capabilities (Article 14)\n• Accuracy, robustness, and cybersecurity (Article 15)\n• Quality management system (Article 17)\n• Deployer obligations: use per instructions, oversight, monitoring, informing workers and affected persons (Article 26)\n• Conformity assessment before market placement (Article 43)\n• Registration in the EU database (Article 49)\n• Post-market monitoring (Article 72)\n\nThe deferral does not reduce the work. It gives you time to do it properly."},{"title":"Serious Incident Reporting (Article 73)","body":"Providers of high-risk AI systems must report serious incidents to the market-surveillance authority of the Member State where the incident occurred. A ''serious incident'' is one that directly or indirectly leads to:\n\n• Death or serious damage to a person''s health\n• Serious and irreversible disruption of critical infrastructure\n• Infringement of obligations under EU law protecting fundamental rights\n• Serious damage to property or the environment\n\nThe report is due immediately after establishing a causal link (or reasonable likelihood of one) and in any event no later than 15 days after the provider becomes aware of the incident. Shorter limits apply: 2 days for a widespread infringement or a serious and irreversible disruption of critical infrastructure, and 10 days in the event of a person''s death. Deployers must inform the provider (and, where relevant, the authorities) without undue delay when they identify a serious incident."}],"quiz":[{"question":"Who in your organisation needs AI literacy training?","options":["Only the IT department","Only managers and executives","Everyone who operates or uses AI systems on the organisation''s behalf","Only the compliance officer"],"correct":2,"explanation":"Article 4 requires measures supporting AI literacy for all personnel who operate or use AI systems, regardless of their role."},{"question":"What is the general deadline for a provider to report a serious incident under Article 73?","options":["Within 24 hours","Within 72 hours","Immediately, and no later than 15 days after becoming aware","At the next annual review"],"correct":2,"explanation":"Article 73 sets a general limit of 15 days from awareness, shortened to 2 days for widespread infringements or critical-infrastructure disruption and 10 days in the event of death."},{"question":"Do Article 50 transparency obligations apply only to high-risk AI systems?","options":["Yes, only high-risk","No, they apply to any AI system that interacts with people or generates content","Only to prohibited systems","Only to GPAI models"],"correct":1,"explanation":"Article 50 applies regardless of risk level, and it has applied since 2 August 2026."}]}', 1, datetime('now'));
INSERT OR REPLACE INTO training_modules (id, title, description, category, tier_required, duration_min, order_index, content_version, regulatory_basis, content, is_published, updated_at) VALUES ('mod_technical_01', 'Risk Classification Deep Dive', 'Master the AI Act''s risk classification system: Annex III categories, the Article 6(3) exception as amended in 2026, Annex I products, and when the high-risk obligations actually apply.', 'technical', 'pro', 30, 5, '2026.09', '["Article 6","Annex I","Annex III","Article 49","Article 111","Article 113"]', '{"sections":[{"title":"The Annex III High-Risk Categories","body":"Annex III defines eight areas where AI systems are considered high-risk:\n\n1. Biometrics (remote identification, categorisation by sensitive attributes, emotion recognition where not prohibited)\n2. Management and operation of critical infrastructure\n3. Education and vocational training (admissions, assessment, proctoring)\n4. Employment, workers'' management, and access to self-employment\n5. Access to essential private and public services (credit scoring, life and health insurance pricing, social benefits, emergency dispatch)\n6. Law enforcement\n7. Migration, asylum, and border control management\n8. Administration of justice and democratic processes\n\nIf your AI system falls within one of these areas AND performs one of the specific use cases listed, it is classified as high-risk by default. The Commission''s guidelines on high-risk classification, published under Article 6(5), give worked examples for each area."},{"title":"The Article 6(3) Exception","body":"Even if an AI system is listed in Annex III, the provider may determine it is NOT high-risk if it does not pose a significant risk of harm to health, safety, or fundamental rights, including by not materially influencing the outcome of decision-making. The exception applies where the system:\n\n• Performs a narrow procedural task\n• Improves the result of a previously completed human activity\n• Detects decision-making patterns or deviations without replacing or influencing a human assessment\n• Performs a preparatory task to an assessment relevant to the Annex III use case\n\nAn AI system that profiles natural persons is always high-risk.\n\nThe 2026 Omnibus kept the paper trail: a provider relying on Article 6(3) must document the assessment before placing the system on the market, provide it to authorities on request, and register the system in the EU database, now through a simplified registration procedure."},{"title":"Safety Components and Annex I Products","body":"An AI system is also classified as high-risk if it is a safety component of, or is itself, a product covered by EU harmonisation legislation listed in Annex I and subject to third-party conformity assessment. This includes:\n\n• Medical devices and in-vitro diagnostics (MDR, IVDR)\n• Machinery and equipment\n• Toys\n• Lifts and pressure equipment\n• Radio equipment\n• Civil aviation\n• Motor vehicles, agricultural vehicles and marine equipment\n\nThese systems are assessed under the sectoral product rules by a Notified Body, with the AI Act requirements integrated into that procedure. Their obligations apply twelve months after the Commission''s standards-availability decision, and no later than 2 August 2028."},{"title":"When the High-Risk Obligations Apply","body":"Under Article 113 as amended by Regulation (EU) 2026/1744:\n\n• Annex III systems: six months after the Commission adopts a decision confirming that harmonised standards, common specifications and guidance are available; backstop 2 December 2027.\n• Annex I systems: twelve months after that decision; backstop 2 August 2028.\n\nLegacy rule (Article 111): high-risk systems already placed on the market or put into service before the applicable date need to comply only if they undergo a significant change in design afterwards, with specific deadlines for public-sector deployers and large-scale EU IT systems. Check the current Article 111 text for the exact dates that apply to your systems.\n\nPractical guidance: classify every system now, record the rationale, and plan so that documentation and conformity assessment are complete well before the backstop. The Commission decision may come with only six months'' notice."}],"quiz":[{"question":"How many high-risk use case areas does Annex III define?","options":["4","6","8","12"],"correct":2,"explanation":"Annex III lists eight broad areas covering biometrics, critical infrastructure, education, employment, essential services, law enforcement, migration, and justice."},{"question":"Under Article 6(3), when can a provider claim an Annex III system is NOT high-risk?","options":["Whenever they want; it''s voluntary","When the system does not pose a significant risk to health, safety, or fundamental rights and does not profile people","Only if the system is open-source","Only for systems placed on the market before 2027"],"correct":1,"explanation":"The exception applies when the system does not pose a significant risk of harm, for example because it performs a narrow procedural or preparatory task. Systems that profile natural persons are always high-risk."},{"question":"Under the 2026 amendments, a provider relying on the Article 6(3) exception must:","options":["Do nothing further","Document the assessment and register the system through the simplified procedure","Obtain Notified Body approval","Notify the AI Office within 72 hours"],"correct":1,"explanation":"The co-legislators rejected the proposal to drop registration. Article 6(3) systems must still be documented and registered, via a simplified registration."}]}', 1, datetime('now'));
INSERT OR REPLACE INTO training_modules (id, title, description, category, tier_required, duration_min, order_index, content_version, regulatory_basis, content, is_published, updated_at) VALUES ('mod_technical_02', 'Technical Documentation (Annex IV)', 'Understand each section of the mandatory technical documentation required for high-risk AI systems, the simplified form for SMEs and small mid-caps, and why to build it now.', 'technical', 'pro', 35, 6, '2026.09', '["Article 11","Annex IV","Article 17","Article 43"]', '{"sections":[{"title":"Purpose of Annex IV Documentation","body":"Article 11 requires providers of high-risk AI systems to draw up technical documentation before the system is placed on the market or put into service. This documentation must:\n\n• Demonstrate that the system complies with all Chapter III, Section 2 requirements\n• Provide authorities and Notified Bodies with the information needed to assess compliance\n• Be kept up to date throughout the system''s lifecycle\n• Be made available to market surveillance authorities upon request\n\nThe documentation is not a one-time exercise. It must be a living record updated whenever the system undergoes substantial modifications.\n\nSMEs and start-ups may provide the elements of Annex IV in a simplified form using the Commission''s simplified technical documentation form. The 2026 amendments extend this relief to small mid-cap companies."},{"title":"The 11 Required Sections","body":"Annex IV requires documentation covering:\n\n1. General description: purpose, developer, version, distribution\n2. Detailed technical description: algorithms, architecture, design choices\n3. Monitoring and control: human oversight, logging, control mechanisms\n4. Risk management: identified risks, mitigations, residual risks\n5. Data governance: training data, bias assessment, GDPR compliance\n6. Performance and accuracy: metrics, robustness, cybersecurity\n7. Transparency: user information, disclosure mechanisms\n8. Conformity assessment: procedure used, standards applied\n9. Post-market monitoring: monitoring plan, incident reporting\n10. Record-keeping: logging capabilities, retention periods\n11. Changes and modifications: version control, modification history"},{"title":"Why Build It Now","body":"The obligation to have Annex IV documentation bites when the high-risk rules apply (no later than 2 December 2027 for Annex III systems and 2 August 2028 for Annex I systems, possibly earlier). But the documentation is also the evidence base for everything else:\n\n• The Article 17 quality management system, now specified by EN 18286:2026, expects the same design, data, testing and monitoring records\n• Conformity assessment (Article 43) and the EU declaration of conformity depend on it\n• Deployers will ask for it during procurement, because Article 26 makes them responsible for using the system per its instructions\n• Article 50 transparency and Article 4 literacy evidence overlap with sections 3, 7 and 10\n\nEffective documentation should be specific, evidence-based, maintained with an owner and review cycle, accessible to a non-specialist auditor, and version-controlled. Comply AI generates templates that cover all 11 sections with guided prompts."}],"quiz":[{"question":"When must Annex IV documentation be prepared?","options":["After the system has been on the market for 1 year","Before the system is placed on the market or put into service","Only when requested by authorities","Only after a serious incident"],"correct":1,"explanation":"Technical documentation must be drawn up before the system is placed on the market, as part of the conformity assessment process."},{"question":"How many sections does Annex IV require in technical documentation?","options":["5","8","11","15"],"correct":2,"explanation":"Annex IV specifies 11 documentation sections covering everything from general description to modification history."},{"question":"Which organisations may use the simplified technical documentation form?","options":["Any provider","SMEs, start-ups and, since 2026, small mid-caps","Only public bodies","Only providers of Annex I products"],"correct":1,"explanation":"Article 11 allows SMEs and start-ups to use the Commission''s simplified form; the Digital Omnibus extended this to small mid-cap companies."}]}', 1, datetime('now'));
INSERT OR REPLACE INTO training_modules (id, title, description, category, tier_required, duration_min, order_index, content_version, regulatory_basis, content, is_published, updated_at) VALUES ('mod_technical_03', 'Data Governance & Bias', 'Learn the data quality, governance, and bias requirements for AI systems under the EU AI Act, including the widened 2026 legal basis for bias-detection data.', 'technical', 'pro', 30, 7, '2026.09', '["Article 10","Article 10(5)","GDPR Articles 6, 9, 22, 35"]', '{"sections":[{"title":"Article 10: Data and Data Governance","body":"High-risk AI systems that use data for training must be developed using training, validation and testing datasets that meet specific quality criteria:\n\n• Relevant, sufficiently representative, and to the best extent possible free of errors and complete in view of the intended purpose\n• Appropriate to the intended purpose and the deployment context, including the geographical, contextual, behavioural or functional setting\n• Examined for possible biases, especially those likely to affect health, safety or fundamental rights or lead to prohibited discrimination\n• Subject to appropriate data governance and management practices covering design choices, collection, preparation, labelling, assumptions and gaps\n\nThe provider must document the data pipeline: collection methods, sources, preparation steps, labelling procedures, and any gaps or limitations identified. The draft European standard prEN 18284 on data quality and governance for AI will give the accepted way to demonstrate this."},{"title":"Bias Detection and Mitigation","body":"Bias in AI systems can lead to discrimination, which directly conflicts with the Act''s goal of protecting fundamental rights. Organisations should:\n\n• Assess training data for representativeness across relevant demographics\n• Test system outputs for disparate impact on different groups\n• Implement mitigation measures (re-sampling, re-weighting, fairness constraints)\n• Document all bias assessments and their outcomes\n• Conduct ongoing monitoring for bias drift after deployment\n\nThe 2026 amendments widened the legal basis in Article 10(5) for processing special categories of personal data (ethnicity, health, religion and similar) for the purpose of bias detection and correction. It now covers providers and deployers of any AI system, not only high-risk providers. The safeguards are strict: processing must be strictly necessary, other data must be insufficient, access must be limited, the data must not be transmitted to third parties, and it must be deleted once the bias has been corrected or the retention period expires."},{"title":"GDPR Intersection","body":"The EU AI Act does not replace GDPR. Both apply simultaneously when personal data is processed. Key intersections include:\n\n• Legal basis for processing personal data in AI training (Article 6 GDPR) and the AI Act''s Article 10(5) basis for special-category data used in bias detection\n• Data Protection Impact Assessment (DPIA) requirements (Article 35 GDPR), which the AI Act''s Fundamental Rights Impact Assessment builds on\n• Data subject rights (access, erasure, objection to automated decisions)\n• Article 22 GDPR: right not to be subject to solely automated decision-making with legal or similarly significant effects\n• Data minimisation and purpose limitation principles\n\nSupervisory authorities for data protection and market-surveillance authorities for the AI Act cooperate; expect one investigation to reference the other regime."}],"quiz":[{"question":"What must training datasets for high-risk AI systems be?","options":["As large as possible","Relevant, representative, and as free of errors as possible","Only from EU sources","Open-source and publicly available"],"correct":1,"explanation":"Article 10 requires training data to be relevant, sufficiently representative, as free of errors as possible, and appropriate to the intended purpose."},{"question":"Does the EU AI Act replace GDPR?","options":["Yes, completely","No, both apply simultaneously","Only for high-risk systems","Only after December 2027"],"correct":1,"explanation":"The AI Act complements GDPR. Both regulations apply when personal data is processed in connection with AI systems."},{"question":"Under the 2026 amendments, who may process special-category personal data strictly for bias detection and correction?","options":["Only providers of high-risk AI systems","Providers and deployers of any AI system, where strictly necessary and with safeguards","Nobody; it is prohibited","Only public authorities"],"correct":1,"explanation":"The Digital Omnibus extended the Article 10(5) legal basis to all AI systems and models, while reintroducing a strict-necessity standard and safeguards."}]}', 1, datetime('now'));
INSERT OR REPLACE INTO training_modules (id, title, description, category, tier_required, duration_min, order_index, content_version, regulatory_basis, content, is_published, updated_at) VALUES ('mod_leadership_01', 'AI Governance for Leaders', 'Strategic guidance for executives and managers on building an AI governance framework, the EN 18286 quality management standard, and the 2026-2028 compliance calendar.', 'leadership', 'pro', 25, 8, '2026.09', '["Article 17","Article 40","Article 4","Article 99","EN 18286:2026"]', '{"sections":[{"title":"Building an AI Governance Framework","body":"Effective AI governance requires commitment from the top. Leaders should:\n\n• Appoint a responsible person or team for AI compliance, with a mandate that covers procurement, development and use\n• Establish an AI system inventory process (the mandatory first step)\n• Define policies for AI procurement, development, and deployment, including generative AI use by staff\n• Create a risk assessment workflow aligned with the Act''s classification system\n• Implement ongoing monitoring and review cycles\n• Assign an owner for regulatory watch: the Commission''s standards-availability decision, Official Journal citations of standards, and guidance from the AI Office\n• Budget for compliance (training, documentation, assessment, tooling)"},{"title":"Quality Management System (Article 17) and EN 18286:2026","body":"Providers of high-risk AI systems must implement a documented quality management system covering compliance strategy, design and testing procedures, data management, post-market monitoring, incident handling, communication with authorities, resource and competence management, and an accountability framework. It must be proportionate to the organisation''s size.\n\nOn 12 July 2026 CEN and CENELEC approved EN 18286:2026, ''Artificial intelligence: Quality management system for EU AI Act regulatory purposes'', drafted by JTC 21 under the Commission''s standardisation request M/613. It is the first AI Act standard to reach final approval and follows a lifecycle model from design to retirement. Until it is cited in the Official Journal it does not yet give a legal presumption of conformity under Article 40, but it is the clearest available statement of what a compliant QMS looks like. Organisations already certified to ISO/IEC 42001 will find substantial overlap.\n\nCompanion standards still in draft: prEN 18228 (AI risk management), prEN 18229 (trustworthiness framework: logging, transparency, human oversight), prEN 18282 (cybersecurity for AI), and prEN 18284 (data quality and governance). The Commission''s decision confirming that these are available is what starts the six- and twelve-month countdown to the high-risk obligations."},{"title":"The 2026-2028 Compliance Calendar for the Board","body":"Board-level checkpoints:\n\n• Now: Article 4 literacy measures and Article 50 transparency are live. Confirm every customer-facing and content-generating system is compliant, and that legacy generative systems will mark output by 2 December 2026.\n• Q4 2026: inventory and classification complete; owners named for each high-risk candidate; gap analysis against EN 18286.\n• 2027: Annex IV documentation, QMS implementation and conformity assessment for Annex III systems, ready before 2 December 2027 or earlier if the Commission decision comes first.\n• 2028: Annex I embedded systems through Notified Body assessment before 2 August 2028.\n\nPenalty exposure: up to EUR 35 million or 7% of worldwide turnover for prohibited practices; EUR 15 million or 3% for most other obligations; EUR 7.5 million or 1% for supplying incorrect information. SMEs and small mid-caps pay the lower of the two figures."},{"title":"Compliance as Competitive Advantage","body":"Early compliance creates business advantages:\n\n• Trust: customers and partners prefer compliant AI providers, and procurement teams now ask for AI Act documentation\n• Market access: non-compliant systems can be withdrawn from the EU market\n• Risk reduction: structured governance catches problems before they become reportable incidents\n• Talent: engineers and researchers prefer organisations with credible AI governance\n• Insurance: demonstrated compliance can lower liability premiums\n• Future-proofing: other jurisdictions are adopting similar frameworks, and EN 18286 plus ISO/IEC 42001 travel well"}],"quiz":[{"question":"What is the mandatory first step in AI compliance?","options":["Hiring external consultants","Creating an AI system inventory","Applying for CE marking","Filing a DPIA"],"correct":1,"explanation":"You cannot assess risk or meet obligations without first knowing which AI systems your organisation uses, develops, or deploys."},{"question":"Which article requires a quality management system for high-risk AI?","options":["Article 4","Article 10","Article 17","Article 50"],"correct":2,"explanation":"Article 17 requires providers of high-risk AI systems to implement a documented quality management system."},{"question":"Which standard, approved in July 2026, specifies the Article 17 quality management system?","options":["ISO/IEC 27001","EN 18286:2026","prEN 18228","GDPR"],"correct":1,"explanation":"EN 18286:2026 was approved by CEN and CENELEC on 12 July 2026 as the first AI Act harmonised-standard candidate. It is not yet cited in the Official Journal."}]}', 1, datetime('now'));
INSERT OR REPLACE INTO training_modules (id, title, description, category, tier_required, duration_min, order_index, content_version, regulatory_basis, content, is_published, updated_at) VALUES ('mod_gpai_01', 'General-Purpose AI & Generative AI Obligations', 'What the Act requires from providers of general-purpose AI models, the GPAI Code of Practice, systemic-risk models, Commission enforcement since August 2026, and what downstream businesses should demand from vendors.', 'technical', 'pro', 30, 9, '2026.09', '["Articles 51-56","Article 101","Article 111(3)","Article 50","GPAI Code of Practice (10 July 2025)"]', '{"sections":[{"title":"What Is a General-Purpose AI Model?","body":"A general-purpose AI (GPAI) model is an AI model that displays significant generality, can competently perform a wide range of distinct tasks, and can be integrated into many downstream systems or applications. Large language models, image and audio generation models, and multimodal foundation models are the typical examples. The Commission''s July 2025 guidelines use a training-compute indicator of around 10^23 floating-point operations, combined with the ability to generate language, image or video, as the working test.\n\nThe model is distinct from the AI system built on it. A company that fine-tunes or integrates a model into a product is a downstream provider of an AI system and, if the modification is significant, may also become a provider of a GPAI model."},{"title":"Provider Obligations (Article 53), In Force Since 2 August 2025","body":"Providers of GPAI models must:\n\n• Draw up and maintain technical documentation on training, testing and evaluation, and provide it to the AI Office on request\n• Provide downstream providers with information and documentation that lets them understand capabilities and limitations and meet their own obligations\n• Put in place a policy to comply with EU copyright law, including respecting rights reservations (text-and-data-mining opt-outs)\n• Publish a sufficiently detailed public summary of the content used for training, using the Commission''s mandatory template\n\nModels released under free and open-source licences are exempt from the first two duties unless they pose systemic risk, but never from the copyright and training-summary duties. Models placed on the market before 2 August 2025 must comply by 2 August 2027."},{"title":"Systemic-Risk Models (Article 55)","body":"A GPAI model is presumed to have systemic risk when the cumulative training compute exceeds 10^25 floating-point operations, or when the Commission designates it. Providers must notify the Commission within two weeks of meeting the threshold.\n\nAdditional obligations: state-of-the-art model evaluation including adversarial testing, assessment and mitigation of systemic risks, tracking and reporting of serious incidents to the AI Office, and adequate cybersecurity for the model and its infrastructure.\n\nEnforcement is centralised in the Commission''s AI Office. Since 2 August 2026 the Commission can request information and model access, order corrective measures, restrict or withdraw a model from the EU market, and impose fines of up to EUR 15 million or 3% of worldwide annual turnover. Breaches dating back to 2 August 2025 are in scope."},{"title":"The GPAI Code of Practice","body":"On 10 July 2025 the AI Office published the final General-Purpose AI Code of Practice. It has three chapters:\n\n• Transparency: a model documentation form covering the Article 53 information duties\n• Copyright: policies, crawler behaviour, respecting rights reservations, and complaint handling\n• Safety and Security: only for systemic-risk models; a safety and security framework, evaluations, incident reporting and cybersecurity measures\n\nSigning is voluntary. Signatories benefit from a presumption that following the Code meets the corresponding obligations and from a lighter-touch supervisory relationship with the AI Office. Non-signatories must demonstrate compliance by other means and can expect more requests for information. The Commission''s July 2025 GPAI guidelines explain scope, the compute thresholds, and how ''placing on the market'' is interpreted."},{"title":"What Downstream Businesses Should Do","body":"Most organisations do not train foundation models, but nearly all use them. As a deployer or downstream provider you should:\n\n• Ask each model vendor for the Article 53 downstream documentation and their Code of Practice status\n• Check that your generative AI systems mark output in a machine-readable way (Article 50(2)) and that you label deepfakes and public-interest text (Article 50(4)); these duties have applied since 2 August 2026\n• Document your own fine-tuning or system-level modifications so you can show whether you have become a provider\n• Note the 2026 amendment: for AI systems built on a GPAI model developed by the same provider or group, the AI Office is now the exclusive supervisor, so escalation paths differ from national-authority supervision\n• Record model versions used in production; a model change can trigger re-assessment"}],"quiz":[{"question":"Since when have GPAI model obligations applied to new models?","options":["2 February 2025","2 August 2025","2 August 2026","2 December 2027"],"correct":1,"explanation":"Chapter V obligations apply to GPAI models placed on the market from 2 August 2025. Legacy models have until 2 August 2027."},{"question":"At what training-compute level is a GPAI model presumed to have systemic risk?","options":["10^23 FLOPs","10^25 FLOPs","10^27 FLOPs","There is no threshold"],"correct":1,"explanation":"Article 51 presumes systemic risk when cumulative training compute exceeds 10^25 floating-point operations; the Commission can also designate models."},{"question":"What are the three chapters of the GPAI Code of Practice?","options":["Transparency, Copyright, and Safety and Security","Risk, Data, and Logging","Ethics, Bias, and Fairness","Marking, Labelling, and Detection"],"correct":0,"explanation":"The final Code published on 10 July 2025 has Transparency and Copyright chapters for all providers and a Safety and Security chapter for systemic-risk models."},{"question":"From when can the Commission fine GPAI providers?","options":["2 August 2025","2 August 2026","2 December 2027","It cannot; only national authorities can"],"correct":1,"explanation":"The Commission''s power to fine GPAI providers up to EUR 15 million or 3% of turnover applies from 2 August 2026, one year after the obligations themselves."}]}', 1, datetime('now'));
INSERT OR REPLACE INTO training_modules (id, title, description, category, tier_required, duration_min, order_index, content_version, regulatory_basis, content, is_published, updated_at) VALUES ('mod_role_hr', 'AI in HR & Recruitment', 'Specific guidance for HR teams on using AI for hiring, performance evaluation, and workforce management: what is prohibited now, what is high-risk, and what to prepare before the amended deadlines.', 'role_specific', 'pro', 25, 10, '2026.09', '["Article 5(1)(f)","Annex III point 4","Article 26","Article 27","Article 50","Article 4"]', '{"sections":[{"title":"HR AI Systems Are High-Risk","body":"The EU AI Act classifies AI used in employment contexts as HIGH RISK (Annex III, point 4). This includes systems used for:\n\n• Recruitment and selection (targeted job advertising, CV screening, candidate ranking, interview analysis)\n• Decisions on employment terms, promotion, or termination\n• Task allocation based on individual behaviour or personal traits\n• Monitoring and evaluation of worker performance and behaviour\n\nIf your organisation uses any AI tool in these areas, full high-risk compliance will be required. Under the amended timeline that is no later than 2 December 2027, and possibly six months after the Commission confirms standards are available."},{"title":"What Applies Right Now","body":"Some rules already bind HR teams today:\n\n• Prohibited (since 2 February 2025): AI that infers emotions of employees or candidates in the workplace, except for medical or safety reasons (Article 5(1)(f)). Webcam ''engagement'' scoring and voice-stress analysis in interviews fall here.\n• AI literacy (Article 4): HR staff who use AI tools must be trained to understand their limits and their role in oversight.\n• Transparency (Article 50, since 2 August 2026): candidates interacting with a recruitment chatbot must be told it is AI; AI-generated content used in public-facing communications must be marked.\n• GDPR Article 22 still restricts solely automated decisions with legal or similarly significant effects, such as automated rejection."},{"title":"Preparing for the High-Risk Deployer Duties","body":"When the high-risk obligations apply, deployers of HR AI must (Article 26):\n\n1. Use the system according to the provider''s instructions and assign human oversight to people with the competence, training and authority to intervene\n2. Ensure input data is relevant and sufficiently representative\n3. Keep the automatically generated logs for at least six months\n4. Inform workers'' representatives and affected workers before putting a high-risk AI system into service at the workplace (Article 26(7))\n5. Inform candidates and employees that they are subject to a high-risk AI system, and explain its role in decisions (Article 26(11))\n6. Public bodies and certain private deployers must complete a Fundamental Rights Impact Assessment (Article 27)\n\nPractical steps now: audit all HR tools for AI components, request Article 13 instructions and compliance documentation from vendors, document how AI outputs feed decisions, and monitor for discriminatory outcomes."}],"quiz":[{"question":"Under the EU AI Act, AI used for recruitment screening is classified as:","options":["Minimal risk","Limited risk","High risk","Unacceptable risk"],"correct":2,"explanation":"AI in employment contexts (hiring, evaluation, task allocation) is classified as high-risk under Annex III, point 4."},{"question":"What should HR teams request from AI tool vendors?","options":["Source code","Instructions for use and compliance documentation showing how they meet AI Act requirements","A written guarantee that the tool is unbiased","EU citizenship proof"],"correct":1,"explanation":"Vendors (providers) must supply instructions for use and compliance documentation. HR teams as deployers should verify this exists and covers the relevant requirements."},{"question":"Using AI to infer employees'' emotions from webcam footage during work is:","options":["Allowed with consent","Prohibited, except for medical or safety reasons","High-risk only","Minimal risk"],"correct":1,"explanation":"Article 5(1)(f) prohibits emotion-recognition AI in the workplace and in education, with narrow exceptions for medical or safety purposes. The ban has applied since 2 February 2025."}]}', 1, datetime('now'));
INSERT OR REPLACE INTO training_modules (id, title, description, category, tier_required, duration_min, order_index, content_version, regulatory_basis, content, is_published, updated_at) VALUES ('mod_role_customer', 'AI in Customer-Facing Operations', 'Guidance for customer service, marketing, and sales teams on chatbots, recommendation systems, and generative content under the Article 50 transparency rules in force since August 2026.', 'role_specific', 'pro', 20, 11, '2026.09', '["Article 50","Article 5","Code of Practice on marking and labelling AI-generated content"]', '{"sections":[{"title":"Transparency Is Non-Negotiable (and Live)","body":"Article 50 has applied since 2 August 2026. If your customers interact with a chatbot, virtual assistant, or any AI-driven interface, you must inform them clearly and at the latest at the first interaction that they are dealing with AI, unless this is obvious to a reasonably well-informed person. This applies even if:\n\n• The chatbot is very human-like\n• The AI only handles initial queries before handing off to a human\n• The system is branded as an ''assistant'' or ''helper''\n\nThe Commission''s Article 50 guidelines (July 2026) expect the disclosure to be clear, timely and accessible. A line buried in terms and conditions does not meet the standard."},{"title":"The Four Article 50 Duties","body":"• 50(1) Providers of systems that interact with people: design them so people are informed they are dealing with AI.\n• 50(2) Providers of generative AI: mark text, image, audio and video output in a machine-readable format that is detectable as artificially generated. Techniques include watermarks, metadata and content credentials, and cryptographic provenance. Systems already on the market before 2 August 2026 had until 2 December 2026.\n• 50(3) Deployers of emotion recognition or biometric categorisation: tell the people exposed to the system.\n• 50(4) Deployers: label deepfakes as artificially generated or manipulated, and label AI-generated or manipulated text published to inform the public on matters of public interest, unless the text went through human review and someone holds editorial responsibility.\n\nContent created before 2 August 2026 does not need to be marked or labelled retroactively. Purely assistive edits (spell-checking, minor image adjustments) are outside the marking duty."},{"title":"Content Generation, Deepfakes and Prohibited Uses","body":"If your marketing team uses AI to generate content:\n\n• AI-generated images, video, and audio that resemble real people, places or events (deepfakes) must be visibly labelled\n• The provider''s machine-readable marking must not be stripped when you edit or republish\n• Exceptions exist for evidently artistic, creative, satirical or fictional works, where the label may be limited so it does not spoil the work\n• Using AI to generate fake endorsements or reviews may be unfair commercial practice and, if it manipulates people to their detriment, can cross into prohibited practices\n• Since the 2026 amendments, AI intended to generate non-consensual intimate imagery is prohibited outright; never deploy ''nudification'' or similar features\n\nThe voluntary Code of Practice on marking and labelling AI-generated content, confirmed by the Commission in July 2026, is the reference for how to do this correctly."}],"quiz":[{"question":"Must customers be told they are speaking with an AI chatbot?","options":["Only if they ask","Yes, always, before or at the start of the interaction","Only for high-risk chatbots","Only in financial services"],"correct":1,"explanation":"Article 50(1) requires that people are informed they are interacting with an AI system, unless this is obvious from the circumstances. This has applied since 2 August 2026."},{"question":"Which content must a deployer label under Article 50(4)?","options":["All marketing copy","Deepfakes, and AI-generated text published to inform the public on matters of public interest","Only images","Internal drafts"],"correct":1,"explanation":"Article 50(4) covers deepfakes and public-interest text; the text duty is lifted where a human has reviewed it and holds editorial responsibility."},{"question":"By when must a generative AI system that was already on the market before 2 August 2026 implement machine-readable marking?","options":["It never has to","2 August 2026","2 December 2026","2 December 2027"],"correct":2,"explanation":"The Digital Omnibus granted a four-month grace period for legacy generative systems, ending 2 December 2026."}]}', 1, datetime('now'));
INSERT OR REPLACE INTO training_modules (id, title, description, category, tier_required, duration_min, order_index, content_version, regulatory_basis, content, is_published, updated_at) VALUES ('mod_role_technical', 'AI Act for Developers & Engineers', 'Technical compliance requirements for teams building, integrating, or maintaining AI systems: logging, robustness, machine-readable marking, and the standards to build against.', 'role_specific', 'pro', 35, 12, '2026.09', '["Article 12","Article 14","Article 15","Article 19","Article 50(2)","EN 18286:2026","prEN 18228","prEN 18229","prEN 18282","prEN 18284"]', '{"sections":[{"title":"Building Compliant AI Systems","body":"If your team develops AI systems, build compliance into the development lifecycle:\n\n• Implement logging that captures inputs, outputs, timestamps, and model version at inference time\n• Design human oversight interfaces that let operators monitor, intervene, and override\n• Build shut-down and fallback mechanisms into production systems\n• Document architecture decisions, training procedures, and evaluation results (this becomes Annex IV)\n• Implement cybersecurity measures against adversarial attacks, data poisoning, model extraction and prompt injection\n• Version-control models, training data references, and configuration\n• Test for accuracy, robustness, and bias before each release\n\nAlign the process with EN 18286:2026 (quality management) and track the draft standards prEN 18228 (risk management), prEN 18229 (logging, transparency and human oversight), prEN 18282 (cybersecurity) and prEN 18284 (data). Building to the drafts now avoids rework when they are cited in the Official Journal."},{"title":"Logging Requirements (Articles 12 and 19)","body":"High-risk AI systems must have automatic logging capabilities that record events over the system''s lifetime, at a level that supports post-market monitoring and traceability. For remote biometric identification systems the Act specifically requires:\n\n• The period of each use (start and end timestamps)\n• The reference database against which input data was checked\n• Input data that led to a match\n• Identification of the natural persons involved in verifying the result\n\nRetention: providers must keep the logs under their control for a period appropriate to the intended purpose and at least six months (Article 19), unless sector-specific law requires longer. Deployers must keep the logs they control for at least six months as well (Article 26(6)). Financial-sector deployers keep them as part of their existing record-keeping duties."},{"title":"Machine-Readable Marking (Article 50(2)), In Force Since 2 August 2026","body":"Providers of AI systems that generate synthetic audio, image, video or text must ensure the output is marked in a machine-readable format and detectable as artificially generated. The techniques must be effective, interoperable, robust and reliable as far as technically feasible, taking into account content type, cost and the state of the art. The Commission''s Code of Practice on marking and labelling describes a layered approach:\n\n• Imperceptible watermarks embedded in the content\n• Provenance metadata and content credentials (for example C2PA-style signed manifests)\n• Cryptographic signatures or fingerprints that survive common transformations\n• Detection APIs so deployers and platforms can verify origin\n\nDeadlines: systems placed on the market from 2 August 2026 must comply immediately; systems already on the market had until 2 December 2026. Code signatories commit to offering detection tools and an interoperability solution by 2 February 2027. If you integrate a third-party model, confirm that its marking survives your post-processing pipeline."},{"title":"Accuracy, Robustness & Cybersecurity (Article 15)","body":"High-risk AI systems must achieve and maintain:\n\n• Appropriate levels of accuracy, declared in the instructions for use\n• Resilience against errors, faults, and inconsistencies in data or the environment\n• Robustness against attempts by third parties to alter use, outputs or performance, including adversarial examples and model poisoning\n• Technical cybersecurity measures appropriate to the risks\n• Redundancy and fail-safe solutions where appropriate\n• For continuously learning systems, safeguards against feedback loops that amplify bias\n\nThese requirements apply throughout the system''s lifecycle, not just at deployment. Post-market monitoring (Article 72) is where you prove they still hold."}],"quiz":[{"question":"What must high-risk AI systems automatically log?","options":["Only errors and exceptions","Events over the system''s lifetime that support traceability, including usage periods, matching inputs, and human-oversight identifiers","Only model performance metrics","Only user demographics"],"correct":1,"explanation":"Article 12 requires automatic recording of events that support traceability and post-market monitoring, with specific fields for biometric identification systems."},{"question":"How long must a provider keep high-risk system logs at minimum?","options":["30 days","At least six months, or longer if the purpose or sector law requires","System lifetime plus 6 months","Indefinitely"],"correct":1,"explanation":"Article 19 requires providers to keep logs for a period appropriate to the intended purpose and of at least six months; deployers have the same minimum under Article 26(6)."},{"question":"Machine-readable marking of AI-generated output is an obligation on:","options":["Deployers only","Providers of generative AI systems","Only high-risk providers","Nobody until 2027"],"correct":1,"explanation":"Article 50(2) places the marking duty on providers of systems that generate synthetic content. It has applied since 2 August 2026, with a grace period to 2 December 2026 for legacy systems."}]}', 1, datetime('now'));
